PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE events (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  price REAL DEFAULT 0,
  free_mode INTEGER DEFAULT 0,
  is_active INTEGER DEFAULT 1,
  qr_code TEXT,
  passcode TEXT,
  created_at TEXT DEFAULT (datetime('now'))
, default_price REAL DEFAULT 0, is_default INTEGER DEFAULT 0);
CREATE TABLE frames (
  id TEXT PRIMARY KEY,
  event_id TEXT,
  name TEXT NOT NULL,
  image_url TEXT,
  sort_order INTEGER DEFAULT 1,
  is_active INTEGER DEFAULT 1,
  category TEXT DEFAULT 'Umum',
  description TEXT,
  created_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE layouts (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  photo_count INTEGER DEFAULT 3,
  slots TEXT,
  is_active INTEGER DEFAULT 1,
  created_at TEXT DEFAULT (datetime('now'))
, ratio TEXT, canvas_width INTEGER, canvas_height INTEGER);
CREATE TABLE frame_layouts (
  id TEXT PRIMARY KEY,
  frame_id TEXT,
  layout_id TEXT,
  image_url TEXT,
  category TEXT,
  created_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE sessions (
  id TEXT PRIMARY KEY,
  event_id TEXT,
  frame_id TEXT,
  layout_id TEXT,
  photos TEXT,
  final_url TEXT,
  preview_url TEXT,
  created_at TEXT DEFAULT (datetime('now'))
, frame_layout_id TEXT, status TEXT DEFAULT 'pending', filter_applied TEXT);
CREATE TABLE orders (
  id TEXT PRIMARY KEY,
  session_id TEXT,
  amount REAL DEFAULT 0,
  payment_status TEXT DEFAULT 'pending',
  payment_method TEXT,
  payment_reference TEXT,
  created_at TEXT DEFAULT (datetime('now'))
, paid_at TEXT, status TEXT DEFAULT 'pending');
CREATE TABLE settings (
  key TEXT PRIMARY KEY,
  value TEXT,
  updated_at TEXT DEFAULT (datetime('now'))
);
